import { cn } from '@postgear/ui';
import { BRAND_MARK, BRAND_TILE_LETTERS, BRAND_WORDMARK } from './brand-paths';

/**
 * The PostGear logo (mark locked 2026-11-05): a gear with 6 tall spokes and a
 * white centre, and the "PostGear" wordmark. The shapes live in
 * `brand-paths.ts`, generated by `apps/web/scripts/generate-brand.mjs` with the
 * favicon and app icons, so every copy of the logo comes from one source. Never
 * redraw it with text.
 *
 * Colours are the flat brand tokens, which no theme changes, so the mark
 * looks the same in every theme like the browser-tab icon does: the gear is
 * actionPrimary blue, the centre white, and the outline the fixed ink of
 * onActionLight (not the theme's outline). The wordmark is the one part that
 * follows the theme: it takes the surrounding text colour (`fill-current`),
 * so it is ink in light mode and white in dark mode.
 *
 * The mark wears a sticker round its outer edge: an ink rim and a white band,
 * with a hard ink shadow under it all. It is the same in light and dark mode.
 * The wordmark stays plain (the owner's pick, 2026-10-27, after comparing a
 * sticker on both).
 *
 * Both are decorative by default. Pass `label` when the logo is the only
 * thing naming the product in that spot, and it is announced as an image.
 */
export function BrandMark({ className, label }: { className?: string; label?: string }) {
  return (
    <svg
      viewBox={BRAND_MARK.viewBox}
      // overflow-visible: the sticker reaches past the gear's own box.
      className={cn('shrink-0 overflow-visible', className)}
      role="img"
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      {/* The white centre goes first, so the hard shadow still falls on it. */}
      <circle
        cx={BRAND_MARK.centre.cx}
        cy={BRAND_MARK.centre.cy}
        r={BRAND_MARK.centre.r}
        className="fill-onActionPrimary"
      />
      <g transform={`translate(${BRAND_MARK.shadow} ${BRAND_MARK.shadow})`}>
        <path d={BRAND_MARK.gear} fillRule="evenodd" className="fill-onActionLight" />
        <path
          d={BRAND_MARK.edge}
          className="fill-none stroke-onActionLight"
          strokeWidth={BRAND_MARK.rim}
          strokeLinejoin="round"
        />
      </g>
      {/* The sticker's rim and white band follow the outer edge only. */}
      <path
        d={BRAND_MARK.edge}
        className="fill-none stroke-onActionLight"
        strokeWidth={BRAND_MARK.rim}
        strokeLinejoin="round"
      />
      <path
        d={BRAND_MARK.edge}
        className="fill-none stroke-onActionPrimary"
        strokeWidth={BRAND_MARK.band}
        strokeLinejoin="round"
      />
      <path
        d={BRAND_MARK.gear}
        fillRule="evenodd"
        className="fill-actionPrimary stroke-onActionLight"
        strokeWidth={BRAND_MARK.outline}
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** "PostGear" as outlined letters. Size it by height (`h-*`); the width follows. */
export function BrandWordmark({ className, label }: { className?: string; label?: string }) {
  return (
    <svg
      viewBox={BRAND_WORDMARK.viewBox}
      width={BRAND_WORDMARK.width}
      height={BRAND_WORDMARK.height}
      className={cn('w-auto shrink-0 fill-current', className)}
      role="img"
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      <path d={BRAND_WORDMARK.d} />
    </svg>
  );
}

/**
 * The product's name inside a heading, button or brand line, drawn in the
 * wordmark's own lettering (2026-11-13) instead of the text font. Use it
 * wherever "PostGear" is shown as a name; sentences (descriptions, errors,
 * toasts) and plain strings (tab titles, metadata) keep the typed word.
 *
 * It sizes itself from the surrounding text, so it needs no size of its own:
 * the letters stand as tall as the text's capitals (Sora's are about 0.72 em,
 * and the outline's capitals are 773 of its 817 units), sit on the same
 * baseline, and take the text's colour. The real word sits beside it for
 * screen readers, find in page and copying, and the two never wrap apart.
 */
export function BrandName({ className }: { className?: string }) {
  return (
    <span className={cn('inline-block whitespace-nowrap', className)}>
      <span className="sr-only">PostGear</span>
      <BrandWordmark className="inline-block h-[0.76em] align-[-0.04em]" />
    </span>
  );
}

/**
 * The sidebar's tile (2026-11-05): the rail's old "P" tile, as it stood until
 * 2026-10-27, now holding "PG" in Luckiest Guy. The sidebar is the only place
 * it appears; the gear (`BrandMark`) stays the logo everywhere else.
 *
 * The letters are outlined path data, so Luckiest Guy is never loaded. They are
 * white with an ink border, the same letters the Logo Lab shows, because plain
 * white ones looked vague on the blue. The border is painted under each letter,
 * so only its outer half shows and each letter keeps its own weight.
 */
export function BrandTile({ className, label }: { className?: string; label?: string }) {
  return (
    <span
      role="img"
      aria-label={label}
      aria-hidden={label ? undefined : true}
      title={label}
      className={cn(
        'flex h-14 w-14 shrink-0 items-center justify-center rounded-xl border-2 border-outline bg-actionPrimary shadow-brutalSm',
        className,
      )}
    >
      <svg
        viewBox={BRAND_TILE_LETTERS.viewBox}
        className="h-7 w-10"
        aria-hidden="true"
        focusable="false"
      >
        {BRAND_TILE_LETTERS.paths.map((d) => (
          <path
            key={d}
            d={d}
            className="fill-onActionPrimary stroke-onActionLight"
            strokeWidth={BRAND_TILE_LETTERS.outline}
            strokeLinejoin="round"
            paintOrder="stroke"
          />
        ))}
      </svg>
    </span>
  );
}
